# quicksort :: [5, 1, 4, 2, 8]
def quicksort(xs):
    if len(xs) <= 1:
        return list(xs)
    pivot = xs[len(xs) // 2]
    less = [x for x in xs if x < pivot]
    equal = [x for x in xs if x == pivot]
    greater = [x for x in xs if x > pivot]
    return quicksort(less) + equal + quicksort(greater)

if __name__ == "__main__":
    print(quicksort([5, 1, 4, 2, 8]))

